<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Exam questions · UIU Recruitment Portal Admin</title><?php $adminSection='exams'; ?><?= $this->include('admin/_styles') ?><style>.file-link{display:block;margin-top:6px;padding:6px 9px;border-radius:6px;background:#eef8ff;color:#168fd4;font-size:12px}</style></head><body><div class="admin-app"><?php $username=session()->get('admin_username');$usertype=session()->get('admin_usertype'); ?><?= $this->include('admin/_sidebar') ?><main class="admin-main"><header class="admin-topbar"><div class="admin-top-title">Exam questions</div><div class="admin-search">⌕ <span>Search...</span><span style="margin-left:auto">⌘ K</span></div><div class="admin-pill">✦ AI insights</div><div style="font-size:20px;color:#778092">☼</div></header><div class="admin-content"><div class="admin-heading"><div><h1><?= esc($exam['title']) ?></h1><p><?= esc($exam['description']) ?> · <?= esc((int)($exam['duration_seconds']/60)) ?> minutes</p></div><a class="admin-btn" href="<?= site_url('admin/questions/new?exam_id=' . $exam['id']) ?>">＋ Add question</a></div><?php if (!$questions): ?><div class="admin-card admin-empty">This exam has no questions yet. Use “Add question” to build it.</div><?php else: ?><div class="admin-table"><table><thead><tr><th>#</th><th>Question</th><th>Type</th><th>Points</th><th>Attachments</th></tr></thead><tbody><?php foreach($questions as $index=>$question): ?><tr><td><?= $index+1 ?></td><td><strong><?= esc($question['prompt']) ?></strong><?php if ($question['hint']): ?><br><small style="color:#798196"><?= esc($question['hint']) ?></small><?php endif; ?></td><td><?= esc($question['type']) ?></td><td><?= esc($question['points']) ?></td><td><?php if ($question['attachments']): ?><?php foreach ($question['attachments'] as $attachment): ?><a class="file-link" href="<?= site_url('admin/questions/' . $question['id'] . '/attachment/' . $attachment['id']) ?>">↧ <?= esc($attachment['original_name']) ?></a><?php endforeach; ?><?php elseif ($question['attachment_path']): ?><a class="file-link" href="<?= site_url('admin/questions/' . $question['id'] . '/attachment') ?>">↧ <?= esc($question['attachment_name']) ?></a><?php else: ?><small style="color:#798196">None</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></main></div></body></html>
